// Calculate the date threshold for follow-up
// Follow-up 1: 3 days after last email
// Follow-up 2: 5 days after follow-up 1
// Follow-up 3: 7 days after follow-up 2
const followUpIntervals = [3, 5, 7];
const today = new Date();

// Build Airtable filter formula
// Get leads where:
// 1. Status is 'Email Sent' or 'Follow-up X Sent'
// 2. Last email was enough days ago
// 3. Follow-up count < 3

const cutoffDate = new Date(today);
cutoffDate.setDate(cutoffDate.getDate() - 3); // minimum 3 days
const cutoffDateStr = cutoffDate.toISOString().split('T')[0];

const filterFormula = `AND(
  OR(
    {Status}='Email Sent',
    {Status}='Follow-up 1 Sent',
    {Status}='Follow-up 2 Sent'
  ),
  {Follow_up_Count} < 3,
  IS_BEFORE({Last_Email_Date}, '${cutoffDateStr}')
)`;

console.log('Follow-up filter:', filterFormula);
console.log('Cutoff date:', cutoffDateStr);

return [{ json: { filterFormula, today: today.toISOString().split('T')[0], cutoffDate: cutoffDateStr } }];

// Check exact follow-up timing based on interval rules
const record = $input.item.json;
const fields = record.fields || record;

const today = new Date();
const lastEmailDate = new Date(fields.Last_Email_Date);
const daysSinceLastEmail = Math.floor((today - lastEmailDate) / (1000 * 60 * 60 * 24));
const followUpCount = parseInt(fields.Follow_up_Count) || 0;

// Follow-up intervals: [3, 5, 7] days
const intervals = [3, 5, 7];
const requiredInterval = intervals[followUpCount] || 7;

const shouldSendFollowUp = daysSinceLastEmail >= requiredInterval;

console.log(`Lead: ${fields.Name}, Days since last: ${daysSinceLastEmail}, Required: ${requiredInterval}, Should send: ${shouldSendFollowUp}`);

// YOUR COMPANY INFO - Update these!
const myCompany = 'XCONS';
const myProduct = 'giải pháp tư vấn và triển khai công nghệ';
const myName = 'Nhật';

const followUpNumber = followUpCount + 1;
const name = fields.Name || '';
const firstName = name.split(' ')[0] || name;

const followUpPrompt = `Hãy viết email follow-up lần ${followUpNumber} cho chiến dịch cold email B2B, bằng tiếng Việt.

Thông tin người nhận:
- Họ tên: ${name}
- Chức danh: ${fields.Title || ''}
- Công ty: ${fields.Company || ''}
- Ngành: ${fields.Industry || ''}
- Gọi bằng: ${firstName}

Lịch sử gửi:
- Email đầu tiên gửi ngày: ${fields.Email_Sent_Date || ''}
- Số ngày đã qua: ${daysSinceLastEmail} ngày
- Đây là follow-up lần thứ: ${followUpNumber}
- Tiêu đề email gốc: ${fields.Email_Subject || ''}
- Chưa có phản hồi từ họ

Thông tin người gửi:
- Công ty: ${myCompany}
- Sản phẩm/Dịch vụ: ${myProduct}
- Tên: ${myName}

Yêu cầu:
1. Ngắn hơn email gốc (80-120 từ)
2. Không lặp lại nội dung cũ
3. Thêm góc nhìn/insight mới hoặc social proof
4. Call to action đơn giản hơn (chỉ cần 1 từ "Có" hay "Không")
5. Giọng văn nhẹ nhàng, không tạo áp lực
${followUpNumber === 3 ? '6. ĐÂY LÀ EMAIL CUỐI CÙNG - Nêu rõ đây là lần cuối bạn liên hệ' : ''}

Trả về CHÍNH XÁC JSON sau (không có text khác):
{
  "subject": "Re: ${fields.Email_Subject || 'Hợp tác với ' + fields.Company}",
  "body": "<nội dung email, dùng \\n để xuống dòng>"
}`;

return [{
  json: {
    record_id: record.id,
    name,
    first_name: firstName,
    email: fields.Email,
    company: fields.Company || '',
    title: fields.Title || '',
    industry: fields.Industry || '',
    original_subject: fields.Email_Subject || '',
    thread_id: fields.Email_Thread_ID || '',
    follow_up_count: followUpCount,
    follow_up_number: followUpNumber,
    days_since_last_email: daysSinceLastEmail,
    should_send: shouldSendFollowUp,
    followUpPrompt
  }
}];

// Parse follow-up email content
const leadData = $('Check Timing & Prepare Prompt').item.json;
const aiResponse = $input.item.json;

let emailContent = { 
  subject: `Re: ${leadData.original_subject}`, 
  body: `Xin chào ${leadData.first_name},\n\nTôi muốn follow up email trước...` 
};

try {
  const content = aiResponse.choices?.[0]?.message?.content || '{}';
  emailContent = JSON.parse(content);
} catch (e) {
  console.error('Failed to parse follow-up email:', e);
}

const htmlBody = emailContent.body
  .replace(/\n/g, '<br>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

return [{
  json: {
    ...leadData,
    subject: emailContent.subject,
    body_plain: emailContent.body,
    body_html: `<div style="font-family: Arial, sans-serif; max-width: 600px; line-height: 1.6;">${htmlBody}</div>`
  }
}];

// Prepare Airtable update data
const leadData = $('Parse Follow-up Content').item.json;
const newFollowUpCount = leadData.follow_up_count + 1;
const today = new Date().toISOString().split('T')[0];

// Determine new status
let newStatus;
if (newFollowUpCount >= 3) {
  newStatus = 'Follow-up 3 Sent';
} else if (newFollowUpCount === 2) {
  newStatus = 'Follow-up 2 Sent';
} else {
  newStatus = 'Follow-up 1 Sent';
}

return [{
  json: {
    record_id: leadData.record_id,
    name: leadData.name,
    company: leadData.company,
    new_follow_up_count: newFollowUpCount,
    new_status: newStatus,
    today
  }
}];
